// De import registreert de elementen; de story registreert vl-button zelf.
import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent } from '@domg-wc/components/atom';
import { VlMap, VlMapBaseLayerGRBGray, VlMapLoadingIndicator } from '@domg-wc/map';
import { MapEvent } from 'ol';

registerWebComponents([VlButtonComponent]);

// Enkel voor de demo: vuur loadstart af op de OpenLayers-kaart (de property map van vl-map), en na ttw milliseconden
// loadend.
const fakeLoadMap = async (ttw) => {
    const vlMap = document.querySelector('vl-map');
    vlMap.map.dispatchEvent(new MapEvent('loadstart', vlMap.map));
    await new Promise((resolve) => setTimeout(resolve, ttw));
    vlMap.map.dispatchEvent(new MapEvent('loadend', vlMap.map));
};

document.querySelector('[data-cy="short-wait"]').addEventListener('click', () => fakeLoadMap(500));
document.querySelector('[data-cy="long-wait"]').addEventListener('click', () => fakeLoadMap(10000));
